// Extrai audio/transcricao e metadados
const body = $input.item.json.body || $input.item.json;

if (!body.audio_url && !body.transcricao) {
  throw new Error('audio_url ou transcricao é obrigatório');
}

const {
  audio_url = '',
  transcricao = '',
  candidato = {},
  entrevistador = {},
  vaga = {},
  tipo = 'completa', // completa | rapida | seguimento
  incluir_analise = true,
  incluir_pontos_atencao = true,
  gerar_resumo_executivo = true
} = body;

return {
  audio_url,
  transcricao,
  candidato,
  entrevistador,
  vaga,
  tipo,
  incluir_analise,
  incluir_pontos_atencao,
  gerar_resumo_executivo
};

// Transcrição de áudio (placeholder - requer integração real)
const { audio_url } = $input.item.json;

// NOTA: Aqui você integraria com serviços de transcrição:
// - OpenAI Whisper API
// - Google Speech-to-Text
// - AWS Transcribe
// - Azure Speech Services

// Por ora, retornamos placeholder
return {
  transcricao: '[TRANSCRICAO DO AUDIO SERA PROCESSADA AQUI]',
  audio_url,
  duracao_segundos: 0,
  idioma_detectado: 'pt-BR',
  confianca: 0.95,
  nota: 'Integração com serviço de transcrição necessária'
};

const { transcricao, systemMessage } = $input.item.json;

const prompt = [
  systemMessage,
  ``,
  `TRANSCRIÇÃO DA ENTREVISTA:`,
  ``,
  `---`,
  transcricao,
  `---`,
  ``,
  `Por favor, gere a memória de entrevista seguindo a estrutura definida acima.`
].join('\n');

return { prompt };

// Formata resposta final
const memoria = $('Processa Memoria').first().json.output;
const dadosOriginais = $('Extrai Dados').first().json;
const analiseData = $('Prepara Analise').first().json;

return {
  code: 200,
  data: {
    memoria_estruturada: memoria,
    transcricao_original: analiseData.transcricao,
    metadados: {
      candidato: dadosOriginais.candidato,
      vaga: dadosOriginais.vaga,
      entrevistador: dadosOriginais.entrevistador,
      tipo: dadosOriginais.tipo,
      data_processamento: new Date().toISOString(),
      audio_url: dadosOriginais.audio_url || null
    },
    acoes_sugeridas: [
      'Adicionar candidato ao banco de talentos',
      'Agendar segunda entrevista se recomendado',
      'Verificar referências profissionais',
      'Compartilhar memória com equipe de recrutamento',
      'Arquivar para consultas futuras'
    ]
  }
};
